package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.utils.BytesUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarArchiveOutputStream#finish()
 */
public class TarArchiveOutputStream_finish_TriageGen2Test {

    @Test
    public void testFinishThrowsIOException() throws IOException {
        // Since the provided code has a hardcoded 'if(true)' that throws IOException,
        // the only possible execution path is the exception path.

        // Arrange
        OutputStream os = BytesUtils.paddingOutputStream(1024);
        TarArchiveOutputStream tar = new TarArchiveOutputStream(os);

        // Act & Assert
        try {
            tar.finish();
            Assert.fail("Expected IOException to be thrown due to hardcoded if(true) block");
        } catch (IOException e) {
            Assert.assertEquals("This archives contains unclosed entries.", e.getMessage());
        } finally {
            tar.close();
        }
    }
}
